  --primary: #1a1a1a;
  --secondary: #4f46e5;
  --bg: #ffffff;
  --text: #1a1a1a;
  --text-muted: #666666;
  --border: #e5e5e5;
  --error: #dc2626;
  --focus-ring: #4f46e5;
  --accent-bg: #f9fafb;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
  line-height: 1.5;
  color: var(--text);
  background-color: var(--bg);
  -webkit-font-smoothing: antialiased;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--secondary);
  color: white;
  padding: 8px;
  z-index: 100;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
}

/* Typography */
h1, h2, h3 {
  font-weight: 700;
  line-height: 1.2;
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

header {
  border-bottom: 1px solid var(--border);
  padding: 1rem 0;
  position: sticky;
  top: 0;
  background: white;
  z-index: 50;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

nav ul {
  display: flex;
  list-style: none;
  gap: 2rem;
}

.nav-link {
  font-weight: 500;
  color: var(--text);
}

.nav-link:focus {
  outline: 2px solid var(--focus-ring);
  outline-offset: 4px;
}

/* Hero Section */
.hero {
  padding: 4rem 0;
  background-color: var(--accent-bg);
  margin-bottom: 4rem;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}

.hero-content h1 {
  font-size: 3.5rem;
  margin-bottom: 1.5rem;
}

.hero-content p {
  font-size: 1.25rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.btn {
  display: inline-block;
  background-color: var(--primary);
  color: white;
  padding: 0.75rem 1.5rem;
  border-radius: 4px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--primary);
  transition: background-color 0.2s;
}

.btn:hover {
  background-color: #333;
  text-decoration: none;
}

.btn:focus {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

/* Sections */
section {
  margin-bottom: 5rem;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 2rem;
}

.section-title {
  font-size: 2rem;
}

/* Product Grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 2rem;
}

.product-card {
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
  transition: transform 0.2s;
  background: white;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

.product-image {
  width: 100%;
  aspect-ratio: 1;
  background-color: #f3f4f6;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.product-info {
  padding: 1.5rem;
}

.product-name {
  font-weight: 600;
  margin-bottom: 0.5rem;
  font-size: 1.1rem;
}

.product-price {
  font-weight: 700;
  color: var(--secondary);
}

.product-tag {
  font-size: 0.75rem;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
  display: block;
}

/* Deals Section */
.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.deal-card {
  position: relative;
  background-color: var(--primary);
  color: white;
  padding: 3rem;
  border-radius: 8px;
  overflow: hidden;
}

.deal-card h3 {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.deal-card p {
  margin-bottom: 2rem;
  opacity: 0.9;
}

/* Editorial */
.editorial {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 4rem;
  align-items: center;
}

.editorial-img {
  width: 100%;
  height: 400px;
  background-color: #e5e7eb;
  border-radius: 8px;
}

.editorial-content h2 {
  font-size: 2.5rem;
  margin-bottom: 1.5rem;
}

/* Footer */
footer {
  background-color: var(--accent-bg);
  padding: 4rem 0;
  border-top: 1px solid var(--border);
}

.footer-inner {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.footer-column h4 {
  margin-bottom: 1.5rem;
}

.footer-column ul {
  list-style: none;
}

.footer-column ul li {
  margin-bottom: 0.75rem;
}

.footer-column ul li a {
  color: var(--text-muted);
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@media (max-width: 768px) {
  .hero-inner, .deals-grid, .editorial {
    grid-template-columns: 1fr;
  }

  .hero-content h1 {
    font-size: 2.5rem;
  }

  .footer-inner {
    grid-template-columns: repeat(2, 1fr);
  }
}
